import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CqGPl1zp.js";const c=JSON.parse('{"title":"Webhook（钉钉、飞书、企微）","description":"","frontmatter":{},"headers":[],"relativePath":"webhook.md","filePath":"webhook.md","lastUpdated":null}'),l={name:"webhook.md"};function i(h,e,n,s,u,b){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="webhook-钉钉、飞书、企微" tabindex="-1">Webhook（钉钉、飞书、企微） <a class="header-anchor" href="#webhook-钉钉、飞书、企微" aria-label="Permalink to &quot;Webhook（钉钉、飞书、企微）&quot;">​</a></h1><h2 id="_1-现状" tabindex="-1">1. 现状 <a class="header-anchor" href="#_1-现状" aria-label="Permalink to &quot;1. 现状&quot;">​</a></h2><p>目前项目中，暂时没有直接集成 Webhook 功能~~~原因是：</p><ul><li>第一，Webhook 的需求量暂时不太大，很少有 GitHub Issue 或者星球用户提出相关需求，所以不想增加 <code>system</code> 模块的复杂性</li><li>第二，暂时没想到一个类似 <a href="./sms">《短信配置》</a> 这种形式，可以把钉钉、飞书、企微等 Webhook 平台统一起来，方便用户配置和使用</li></ul><p>当然，项目本身其实有比较精简的 Webhook 功能，比如：</p><ul><li>DebugDingTalkSmsClient 类，模拟短信发送，使用钉钉机器人来接收消息</li><li>有球友 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/pulls/1379" target="_blank" rel="noreferrer">《Pull Request：添加钉钉机器人消息发送功能》</a> + <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3/pulls/788" target="_blank" rel="noreferrer">#788</a> ，一起聊过也不算特别满意</li></ul><h2 id="_2-期望" tabindex="-1">2. 期望 <a class="header-anchor" href="#_2-期望" aria-label="Permalink to &quot;2. 期望&quot;">​</a></h2><p>① 类似 <a href="https://github.com/terminux/ding-talk-spring-boot" target="_blank" rel="noreferrer">https://github.com/terminux/ding-talk-spring-boot</a> 这种形式，但是需要额外：</p><ul><li>支持飞书、企微等平台</li><li>不仅仅支持 yaml 配置文件，也支持数据库配置（类似短信配置）</li></ul><p>其它相似项目：</p><ul><li>飞书：<a href="https://gitee.com/fandylin/feishu-alert-robot-starter" target="_blank" rel="noreferrer">https://gitee.com/fandylin/feishu-alert-robot-starter</a></li><li>企微：<a href="https://github.com/group-robot/work-weixin-robot-java" target="_blank" rel="noreferrer">https://github.com/group-robot/work-weixin-robot-java</a></li></ul><p>② 类似 <a href="https://github.com/ymlluo/group-robot" target="_blank" rel="noreferrer">https://github.com/ymlluo/group-robot</a> 这种形式，但是它是 PHP 实现，需要有 Java 版本。</p>',12)])])}const d=t(l,[["render",i]]);export{c as __pageData,d as default};
